def parse_script(text):
    nodes_list = []
    edges = []
    nodes_dict = {}

    current_node = None
    first_node_id = None

    for line in text.splitlines():
        line = line.strip()
        if not line:
            continue

        # Node header: [NodeID]
        if line.startswith('[') and line.endswith(']'):
            node_id = line[1:-1].strip()
            if first_node_id is None:
                first_node_id = node_id

            current_node = {
                "id": node_id,
