                if ":" in content:
                    c_parts = content.split(":", 1)
                    current_node["speaker"] = c_parts[0].strip()
                    current_node["text"] = c_parts[1].strip()
                else:
                    current_node["text"] = content

                current_node["type"] = "line"
                edges.append({
                    "from": current_node["id"],
                    "to": target_id,
                    "text": ""
                })

